function lateFee(dueDate, paidDate, amount) {
  var days = (paidDate.getTime() - dueDate.getTime()) / 86400000;
  var weeks = Math.ceil(days / 7);
  if (weeks > 3) {
    weeks = 3;
  }
  return weeks * 0.015 * amount;
}
